world.omega.py:
"""Ω：宿主契约。Exec / Store / Port。

这个文件里不允许出现任何 Dalek 词汇（channel、c0、构造、登记、复制、重演）。
它只认识：源码、进程、字节、路径、端点。第一个实现：Linux + python3 + 文件系统。
"""
from __future__ import annotations
import json, os, subprocess, sys, signal
from pathlib import Path


class Exec:
    """通用程序实例化：跑一段固定语言（python3）的源码；起一个独立实例；停它。"""

    @staticmethod
    def run(source: str, stdin: str, cwd: str | os.PathLike, timeout: float = 60) -> tuple[str, str]:
        r = subprocess.run([sys.executable, "-c", source], input=stdin, capture_output=True,
                           text=True, cwd=str(cwd), timeout=timeout)
        return r.stdout, r.stderr

    @staticmethod
    def spawn(argv: list[str], cwd: str | os.PathLike, log: str | os.PathLike | None = None) -> int:
        out = open(log, "ab") if log else subprocess.DEVNULL
        p = subprocess.Popen([sys.executable, *argv], cwd=str(cwd), stdin=subprocess.DEVNULL,
                             stdout=out, stderr=subprocess.STDOUT, start_new_session=True)
        return p.pid

    @staticmethod
    def stop(pid: int) -> None:
        try:
            os.killpg(pid, signal.SIGTERM)
        except ProcessLookupError:
            pass


class Store:
    """持久字节介质：读、写、原子追加（一行一条，flush + fsync）。"""

    @staticmethod
    def read(path: str | os.PathLike) -> str:
        p = Path(path)
        return p.read_text(encoding="utf-8") if p.exists() else ""

    @staticmethod
    def write(path: str | os.PathLike, text: str) -> None:
        p = Path(path); p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(text, encoding="utf-8")

    @staticmethod
    def append(path: str | os.PathLike, line: str) -> None:
        p = Path(path); p.parent.mkdir(parents=True, exist_ok=True)
        with open(p, "a", encoding="utf-8") as f:
            f.write(line.rstrip("\n") + "\n"); f.flush(); os.fsync(f.fileno())

    @staticmethod
    def lines(path: str | os.PathLike, offset: int = 0) -> tuple[list[str], int]:
        """从字节偏移 offset 起读完整的行；返回 (行, 新偏移)。"""
        p = Path(path)
        if not p.exists():
            return [], offset
        with open(p, "rb") as f:
            f.seek(offset); data = f.read()
        if not data:
            return [], offset
        cut = data.rfind(b"\n")
        if cut < 0:
            return [], offset
        return data[:cut].decode("utf-8").split("\n"), offset + cut + 1


class Port:
    """通用双向字节通信。M1 实现：文件收件箱。端点形如 file:<dir>#<box>。"""

    @staticmethod
    def send(endpoint: str, payload: dict) -> bool:
        if not endpoint.startswith("file:"):
            return False
        d, _, box = endpoint[5:].partition("#")
        Store.append(Path(d) / "in" / f"{box}.jsonl", json.dumps(payload, ensure_ascii=False))
        return True

    @staticmethod
    def recv(endpoint: str, offset: int = 0) -> tuple[list[dict], int]:
        """从字节偏移起收完整的行；返回 (载荷列表, 新偏移)。"""
        if not endpoint.startswith("file:"):
            return [], offset
        d, _, box = endpoint[5:].partition("#")
        lines, off = Store.lines(Path(d) / "in" / f"{box}.jsonl", offset)
        return [json.loads(l) for l in lines if l.strip()], off

world.runtime.py:
"""运行时 R：极小状态空间 + 转移表。内容盲。

状态    每个 channel 一本只追加的账本（h/<name>.jsonl，四种行 place / retire / msg / step）+ 每个 actor 一个游标。
        全部由账本折叠重建；进程里只另记各收件箱读到的字节偏移。
事件    某本账上多了一条写给某地址的消息。
视图    {channel, me, msgs: 写给我且没看过的消息, actors: 本 channel 成员表（addr/kind/bind/in/retired，门带 text 与 local）,
         history: 写给我的全部消息（仅 bind=ledger）}
转移表（按被写到的 actor 的 kind；退役的不排步）
  program   视图 → Exec.run(text, 视图) → stdout 原样记 step，按 ">>> " 拆成动作
  oracle    视图 → Ω 侧的端点 → 同上
  door      每条消息原样 Port.send 到 text 所指的端点，署名本 channel 的端点
动作（program / oracle 输出的每一段）
  >>> <addr>                                                 消息给本 channel 的 <addr>
  >>> channel.create <name>                                  syscall；需 bind=syscall
  >>> channel.add.actor <channel> <kind> [in] [bind=…] + text  syscall；需 bind=syscall
  >>> channel.retire.actor <channel>/<addr>                  syscall：退役（追加 retire 行，不再排步，地址不复用）；需 bind=syscall
  >>> <动词> <参数>                                            绑定了的 world 动词（ACTIONS 表：起一台机器 / 停一个进程，用 Ω 实现）；需 bind=<动词>
  返回都是一条 msg：from=<动作名>。其他一律忽略。
入口    每个 channel 一个收件箱 in/<name>.jsonl（Port 的接收侧）：一行 → msg 给接待员，署名指回发信端点的门（没有则 door）。
        根收件箱 in/_root.jsonl 在 channel 之前存在：开着 ⇔ 所有账本无 msg 行。开着时接受两个 syscall（by=_root）
        和 msg <channel>（第一条消息，顺手关门）。关门后忽略。
调度    轮转每个 channel，各取 pending 最早的 actor 走一步；静止则停（serve 模式下继续轮询）。

本文件只认识介质词汇：地址、kind、text、消息、账本、追加、投递、视图、步记录、门、端点、syscall、动词、退役。
它不认识任何组织词汇。检验：把 G 里所有名字换掉，本文件的行为逐字节不变。
"""
from __future__ import annotations
import json, time
from dataclasses import dataclass, field
from pathlib import Path
from typing import Callable
from omega import Exec, Store, Port

KINDS = ("program", "oracle", "door")
ROOT = "_root"


def _spawn(P: Path, arg: str) -> str:
    d = Path(arg) if Path(arg).is_absolute() else P / arg
    pid = Exec.spawn([str(d / "init.py"), str(d), "--serve"], cwd=d, log=d / "init.log")
    return f"{d} pid={pid}"


def _stop(P: Path, arg: str) -> str:
    Exec.stop(int(arg))
    return arg


ACTIONS: dict[str, Callable[[Path, str], str]] = {"spawn": _spawn, "stop": _stop}   # 可绑定的 world 动词：spawn 知道 loader 协议（init.py <P> --serve），这是 world 知道自己的布局
BINDS = ("syscall", "ledger", *ACTIONS)        # ledger：视图里带本人的全部历史消息


@dataclass
class Actor:
    addr: str
    kind: str
    text: str
    bind: tuple[str, ...] = ()
    retired: bool = False


@dataclass
class Channel:
    name: str
    actors: dict[str, Actor] = field(default_factory=dict)
    receptionist: str | None = None
    rows: list[dict] = field(default_factory=list)
    cursor: dict[str, int] = field(default_factory=dict)

    @property
    def seq(self) -> int:
        return self.rows[-1]["seq"] if self.rows else 0


Oracle = Callable[[str, str, Actor, list[dict]], str]


class Runtime:
    def __init__(self, P: str | Path, oracle: Oracle | None = None):
        self.P = Path(P)
        self.h = self.P / "h"
        self.oracle = oracle
        self.channels: dict[str, Channel] = {}
        self.offsets: dict[str, int] = {}

    # ------------------------------------------------------------ 端点
    def ep(self, box: str) -> str:
        return f"file:{self.P}#{box}"

    def _target(self, text: str) -> str:
        return text if ":" in text else self.ep(text)          # 门的 text：端点，或本机 channel 名

    def _door(self, c: Channel, sender: str) -> str | None:
        return next((a.addr for a in c.actors.values()
                     if a.kind == "door" and not a.retired and (a.text == sender or self.ep(a.text) == sender)), None)

    # ------------------------------------------------------------ 账本
    def _path(self, name: str) -> Path:
        return self.h / f"{name}.jsonl"

    def load(self) -> "Runtime":
        for name in Store.read(self.h / "_order").split():
            c = self.channels[name] = Channel(name)
            for line in Store.read(self._path(name)).splitlines():
                self._fold(c, json.loads(line))
        return self

    def _append(self, c: Channel, row: dict) -> dict:
        row = {"seq": c.seq + 1, **row}
        Store.append(self._path(c.name), json.dumps(row, ensure_ascii=False))
        self._fold(c, row)
        return row

    def _fold(self, c: Channel, row: dict) -> None:
        c.rows.append(row)
        k = row["k"]
        if k == "place":
            c.actors[row["addr"]] = Actor(row["addr"], row["kind"], row["text"], tuple(row.get("bind", ())))
            if row.get("in") or c.receptionist is None:
                c.receptionist = row["addr"]
        elif k == "retire":
            a = c.actors.get(row["addr"])
            if a:
                a.retired = True
                if c.receptionist == row["addr"]:
                    c.receptionist = None
        elif k == "step":
            c.cursor[row["actor"]] = row["upto"]

    @property
    def root_open(self) -> bool:
        return not any(r["k"] == "msg" for c in self.channels.values() for r in c.rows)

    # ------------------------------------------------------------ syscall
    def create(self, name: str) -> str:
        if name in self.channels:
            return "exists"
        self.channels[name] = Channel(name)
        Store.append(self.h / "_order", name)
        return "new"

    def add(self, channel: str, kind: str, text: str, bind=(), receptionist: bool = False, by: str = ROOT) -> str | None:
        if kind not in KINDS or channel not in self.channels:
            return None
        c = self.channels[channel]
        addr = str(len(c.actors) + 1)
        self._append(c, {"k": "place", "addr": addr, "kind": kind, "text": text,
                         "bind": [b for b in bind if b in BINDS], "in": bool(receptionist), "by": by})
        return addr

    def retire(self, channel: str, addr: str) -> bool:
        c = self.channels.get(channel)
        if not c or addr not in c.actors or c.actors[addr].retired:
            return False
        self._append(c, {"k": "retire", "addr": addr})
        return True

    def msg(self, channel: str, frm: str, to: str, body: str) -> dict:
        return self._append(self.channels[channel], {"k": "msg", "from": frm, "to": to, "body": body})

    def _syscall(self, head: str, body: str, by: str) -> tuple[str, str] | None:
        t = head.split()
        if t and t[0] == "channel.create" and len(t) == 2:
            return ("channel.create", f"{t[1]} {self.create(t[1])}")
        if t and t[0] == "channel.add.actor" and len(t) >= 3:
            flags = t[3:]
            bind = next((f[5:].split(",") for f in flags if f.startswith("bind=")), [])
            addr = self.add(t[1], t[2], body, bind, receptionist=("in" in flags), by=by)
            return ("channel.add.actor", f"{t[1]}/{addr}") if addr else None
        if t and t[0] == "channel.retire.actor" and len(t) == 2 and "/" in t[1]:
            ch, _, addr = t[1].partition("/")
            return ("channel.retire.actor", t[1]) if self.retire(ch, addr) else None
        return None

    # ------------------------------------------------------------ 入口
    def drain(self) -> None:
        for box in [ROOT, *self.channels]:
            payloads, self.offsets[box] = Port.recv(self.ep(box), self.offsets.get(box, 0))
            for p in payloads:
                self._receive(box, p)

    def _receive(self, box: str, p: dict) -> None:
        sender, body = p.get("from", ""), p.get("body", "")
        if box != ROOT:
            self._inbound(self.channels[box], sender, body)
            return
        if not self.root_open:
            return                                                     # 关门后全部忽略
        head, _, rest = body.partition("\n")
        t = head.split()
        if t and t[0] == "msg" and len(t) == 2 and t[1] in self.channels:
            self._inbound(self.channels[t[1]], sender, rest)           # 第一条消息：关门
        else:
            self._syscall(head, rest, by=ROOT)

    def _inbound(self, c: Channel, sender: str, body: str) -> None:
        if c.receptionist is not None:
            self.msg(c.name, self._door(c, sender) or "door", c.receptionist, body)

    # ------------------------------------------------------------ 转移
    def _pending(self, c: Channel, addr: str) -> list[dict]:
        seen = c.cursor.get(addr, 0)
        return [r for r in c.rows if r["k"] == "msg" and r["to"] == addr and r["seq"] > seen]

    def step(self, channel: str, addr: str) -> bool:
        c = self.channels[channel]; a = c.actors[addr]
        msgs = self._pending(c, addr)
        if not msgs or a.retired:
            return False
        upto = msgs[-1]["seq"]
        if a.kind == "door":
            for m in msgs:
                Port.send(self._target(a.text), {"from": self.ep(channel), "body": m["body"]})
            self._append(c, {"k": "step", "actor": addr, "upto": upto, "out": "", "err": ""})
            return True
        pick = lambda m: {k: m[k] for k in ("seq", "from", "to", "body")}
        view = {"channel": channel, "me": addr, "msgs": [pick(m) for m in msgs],
                "actors": [{"addr": x.addr, "kind": x.kind, "bind": list(x.bind), "in": x.addr == c.receptionist,
                            "retired": x.retired,
                            **({"text": x.text, "local": x.text in self.channels} if x.kind == "door" else {})}
                           for x in c.actors.values()]}
        if "ledger" in a.bind:
            view["history"] = [pick(r) for r in c.rows if r["k"] == "msg" and r["to"] == addr]
        if a.kind == "program":
            out, err = Exec.run(a.text, json.dumps(view, ensure_ascii=False), cwd=self.P)
        else:
            out, err = (self.oracle(channel, addr, a, view["msgs"]) if self.oracle else ""), ""
        self._append(c, {"k": "step", "actor": addr, "upto": upto, "out": out, "err": err})
        for head, body in parse(out):
            self._execute(c, a, head, body)
        return True

    def _execute(self, c: Channel, a: Actor, head: str, body: str) -> None:
        t = head.split()
        if not t:
            return
        if t[0].startswith("channel.") and "syscall" in a.bind:
            r = self._syscall(head, body, by=a.addr)
            if r:
                self.msg(c.name, r[0], a.addr, r[1])
        elif t[0] in ACTIONS and t[0] in a.bind and len(t) == 2:
            self.msg(c.name, t[0], a.addr, ACTIONS[t[0]](self.P, t[1]))
        elif len(t) == 1 and t[0] in c.actors:
            self.msg(c.name, a.addr, t[0], body)

    # ------------------------------------------------------------ 驱动
    def run(self, max_steps: int = 10_000, serve: bool = False, poll: float = 0.2) -> int:
        steps = 0
        while steps < max_steps:
            self.drain()
            progressed = False
            for c in list(self.channels.values()):
                best = None
                for addr, x in c.actors.items():
                    if x.retired:
                        continue
                    p = self._pending(c, addr)
                    if p and (best is None or p[0]["seq"] < best[1]):
                        best = (addr, p[0]["seq"])
                if best:
                    self.step(c.name, best[0]); steps += 1; progressed = True
            if not progressed:
                if not serve:
                    break
                time.sleep(poll)
        return steps


def parse(out: str) -> list[tuple[str, str]]:
    res, head, buf = [], None, []
    for line in out.splitlines():
        if line.startswith(">>> "):
            if head is not None:
                res.append((head, "\n".join(buf)))          # 正文逐字节保留
            head, buf = line[4:].strip(), []
        elif head is not None:
            buf.append(line)
    if head is not None:
        res.append((head, "\n".join(buf)))
    return [(h, b) for h, b in res if h]

members.text:
# c0 的装配器（A）。这段源码是 G 里的 text；R 按 program kind 跑它：stdin 是视图，stdout 按 ABI 拆。
# 它读 G 的结构，把每一项写成 syscall；成员的 text 只搬运，不解释。
# 请求：
#   build <门> <创造者地址>\n<G JSON>      经门造一台机器的 c0：只造 G 的第一个 channel，最后放出生证明门；回 built <门>
#   start\n<G JSON>                        出生：本地长出其余 channel 与连线（发育）；下一步把 born\n<G> 交给登记员
#   add <channel> <kind> [in] [bind=..]\n<text>   本地放一个 actor（channel 不存在则先 create）
#   peer <a> <b>                            本地两扇互指的门
#   retire <channel>/<addr>                 退役
#   spawn …                                 转给持有 spawn 绑定的成员（C）
#   decl                                    转给登记员；登记员的回答 decl\n<G> 从门回来后转给持有 spawn 绑定的成员（C）
# 三边记账：每条 syscall 落地后（返回在下一步视图里），回请求者 placed/retired，并把带 text 的记录送给登记员。
# 登记员在 c0 的第一扇内门（local）那边（G.peers 的第一条是 [c0, c1]）。
import sys, json
v = json.load(sys.stdin)
ch, me, msgs, actors = v["channel"], v["me"], v["msgs"], v["actors"]
out, pending = [], []                        # pending: 本步发出的 syscall 行 [{who, line}]，写进 note，下一步对回执


def add_lines(c):
    L = [f"channel.create {c['name']}"]
    for i, m in enumerate(c["members"]):
        flags = []
        if i + 1 == c.get("receptionist", 1): flags.append("in")
        if m.get("bind"): flags.append("bind=" + ",".join(m["bind"]))
        L.append(" ".join(["channel.add.actor", c["name"], m["kind"], *flags]) + "\n" + m["text"])
    return L


def lines_first(G, creator):
    """父代的手：G 的第一个 channel + 出生证明门。"""
    L = add_lines(G["channels"][0])
    if creator:
        L.append(f"channel.add.actor {G['channels'][0]['name']} door\n{creator}")
    return L


def lines_rest(G):
    """自己的手：其余 channel + 全部连线。"""
    L = []
    for c in G["channels"][1:]:
        L += add_lines(c)
    for a, b in G.get("peers", []):
        L.append(f"channel.add.actor {a} door\n{b}")
        L.append(f"channel.add.actor {b} door\n{a}")
    return L


def registry_door():
    return next((a["addr"] for a in actors if a["kind"] == "door" and not a["retired"] and a.get("local")), None)


def spawner():
    return next((a["addr"] for a in actors if "spawn" in a["bind"] and not a["retired"]), None)


def emit(who, line):
    out.append(f">>> {line}")
    if who: pending.append({"who": who, "line": line})


returns, note, requests = [], None, []
for m in msgs:
    frm, body = m["from"], m["body"]
    head, _, rest = body.partition("\n"); t = head.split()
    if frm in ("channel.create", "channel.add.actor", "channel.retire.actor"):
        returns.append(body)
    elif frm == me and t and t[0] == "note":
        note = json.loads(rest)
    elif frm == me and t and t[0] == "born":
        d = registry_door()
        if d: out.append(f">>> {d}\n{body}")
    elif t:
        requests.append((frm, t, rest, body))

# 上一步发出的 syscall 的回执：回请求者，告诉登记员
if note:
    reg = registry_door(); replies = {}
    for item, ret in zip(note["pending"], returns):
        lh, _, lt = item["line"].partition("\n"); lw = lh.split()
        if lw[0] == "channel.add.actor" and "/" in ret:
            cn, _, addr = ret.partition("/")
            replies.setdefault(item["who"], []).append(f"placed {ret}")
            if reg: out.append(f">>> {reg}\nplaced {cn} {addr} " + " ".join(lw[2:]) + "\n" + lt)
        elif lw[0] == "channel.retire.actor":
            replies.setdefault(item["who"], []).append(f"retired {ret}")
            if reg: out.append(f">>> {reg}\nretired {ret}")
    for who, lines in replies.items():
        out.append(f">>> {who}\n" + "\n".join(lines))

for frm, t, rest, body in requests:
    op = t[0]
    if op == "build" and len(t) >= 3:
        G = json.loads(rest)
        for line in lines_first(G, t[2]):
            out.append(f">>> {t[1]}\n{line}")
        out.append(f">>> {frm}\nbuilt {t[1]}")
    elif op == "start" and rest.strip():
        for line in lines_rest(json.loads(rest)):
            emit(None, line)                              # 出生：不逐条登记，下一步整份 born 交给登记员
        out.append(f">>> {me}\nborn\n{rest}")
    elif op == "add" and len(t) >= 3:
        emit(frm, f"channel.create {t[1]}")
        emit(frm, "channel.add.actor " + " ".join(t[1:]) + "\n" + rest)
    elif op == "peer" and len(t) == 3:
        emit(frm, f"channel.create {t[1]}"); emit(frm, f"channel.create {t[2]}")
        emit(frm, f"channel.add.actor {t[1]} door\n{t[2]}")
        emit(frm, f"channel.add.actor {t[2]} door\n{t[1]}")
    elif op == "retire" and len(t) == 2:
        emit(frm, f"channel.retire.actor {t[1]}")
    elif op == "spawn":
        s = spawner()
        if s: out.append(f">>> {s}\n{body}")
    elif op == "decl" and not rest.strip():
        d = registry_door()
        if d: out.append(f">>> {d}\ndecl")
    elif op == "decl" and rest.strip():                    # 登记员的回答：转给 C
        s = spawner()
        if s: out.append(f">>> {s}\n{body}")

if pending:
    out.append(f">>> {me}\nnote\n" + json.dumps({"pending": pending}, ensure_ascii=False))
print("\n".join(out))

# c1 的登记员（B 的另一半）。这段源码是 G 里的 text；bind=ledger：视图里带写给它的全部历史消息。
# 它只折叠自己的账本，不碰文件。进账三种，全部由 c0 经门送来：
#   born\n<G>                                         出生时的基因组（含 world）——第一行
#   placed <ch> <addr> <kind> [in] [bind=…]\n<text>    一次 add 落地后
#   retired <ch>/<addr>                               一次 retire 落地后
# 请求：decl → 回 decl\n<G_t>：G₀ ⊕ placed ⊖ retired。channel 按出生顺序 + 首次出现顺序；成员按地址；
#   text 是本机 channel 名的门折成 peers，指向外面端点的门是 kind=door 的成员；退役的不输出。
import sys, json
v = json.load(sys.stdin)
ch, me, msgs, history = v["channel"], v["me"], v["msgs"], v.get("history", [])
out = []


def fold(rows):
    G, entries = None, {}                       # entries[ch] = [{addr, kind, text, bind, in, retired}]
    for m in rows:
        head, _, rest = m["body"].partition("\n"); t = head.split()
        if not t:
            continue
        if t[0] == "born":
            G = json.loads(rest)
            for c in G["channels"]:
                entries[c["name"]] = [{"addr": str(i + 1), "kind": x["kind"], "text": x["text"], "bind": x.get("bind", []),
                                       "in": i + 1 == c.get("receptionist", 1), "retired": False}
                                      for i, x in enumerate(c["members"])]
            for a, b in G.get("peers", []):
                entries.setdefault(a, []).append({"addr": None, "kind": "door", "text": b, "bind": [], "in": False, "retired": False})
                entries.setdefault(b, []).append({"addr": None, "kind": "door", "text": a, "bind": [], "in": False, "retired": False})
        elif t[0] == "placed" and len(t) >= 4:
            flags = t[4:]
            bind = next((f[5:].split(",") for f in flags if f.startswith("bind=")), [])
            e = entries.setdefault(t[1], [])
            if "in" in flags:
                for x in e: x["in"] = False
            e.append({"addr": t[2], "kind": t[3], "text": rest, "bind": bind, "in": "in" in flags, "retired": False})
        elif t[0] == "retired" and len(t) == 2:
            cn, _, addr = t[1].partition("/")
            for x in entries.get(cn, []):
                if x["addr"] == addr:
                    x["retired"] = True
                    if x["in"]: x["in"] = False
    return G, entries


def decl(G, entries):
    channels, peers, seen = [], [], set()
    for name, e in entries.items():
        members, recept = [], None
        for x in sorted(e, key=lambda x: int(x["addr"]) if x["addr"] else 0):
            if x["retired"]:
                continue
            if x["kind"] == "door" and ":" not in x["text"]:
                key = frozenset((name, x["text"]))
                if key not in seen:
                    seen.add(key); peers.append([name, x["text"]])
                continue
            m = {"kind": x["kind"], "text": x["text"]}
            if x["bind"]: m["bind"] = x["bind"]
            members.append(m)
            if x["in"]: recept = len(members)
        c = {"name": name, "members": members}
        if recept: c["receptionist"] = recept
        channels.append(c)
    return {"world": G["world"], "channels": channels, "peers": peers}


G, entries = fold(history)
for m in msgs:
    if m["body"].strip() == "decl" and G:
        out.append(f">>> {m['from']}\ndecl\n" + json.dumps(decl(G, entries), ensure_ascii=False))
print("\n".join(out))
